/// `auth`: its subcommands, with the flags of the app's [`Auth`] on `auth login`.
pub(super) fn command(app: &App) -> Command {
    let prefix = app.env_prefix;
    let mut login = Command::new("login")
        .about("Log in and store the credential in a profile")
        .long_about(format!(
            "Log in and store the credential in a profile of the config file. --api-key \
             stores that key, --api-key-stdin the first line of stdin; without them an API key \
             is prompted for (hidden) or read from stdin, unless a flag below picks another \
             way. --profile names the profile (default: the default profile) and --base-url is \
             stored with it.{}\n\n{prefix}_API_KEY needs no login.",
            match keyring::ENABLED {
                true => " Secrets go to the OS keyring when there is one, else to the file.",
                false => "",
            }
        ))
        .arg(
            Arg::new("api-key-stdin")
                .long("api-key-stdin")
                .action(ArgAction::SetTrue)
                .help("Store the API key read from stdin, a terminal's too"),
        )
        .args(app.auth.login_args());
    if keyring::ENABLED {
        login = login.arg(
            Arg::new("no-keyring")
                .long("no-keyring")
                .action(ArgAction::SetTrue)
                .help(format!(
                    "Store the secrets in the config file, not the OS keyring [env: {prefix}_NO_KEYRING]"
                )),
        );
    }
    Command::new("auth")
        .about("Manage credentials and profiles")
        .subcommand_required(true)
        .subcommand(login)
        .subcommand(Command::new("logout").about("Remove the credential of a profile"))
        .subcommand(
            Command::new("status")
                .about("Show the credential commands use: profile, method, expiry, base URL")
                .long_about(
                    "Show the credential commands use, without its secret: the profile, where \
                     the credential comes from, the login method, when it expires, the base URL. \
                     Exits 6 when there is none.",
                ),
        )
        .subcommand(
            Command::new("token")
                .about("Print the bearer token commands send, refreshed if needed")
                .long_about(
                    "Print the bearer token commands send, refreshed first if it expires \
                     within a minute, for other tools: \
                     curl -H \"Authorization: Bearer $(acme auth token)\" ...",
                ),
        )
        .subcommand(Command::new("profiles").about("List the profiles of the config file"))
}

pub type BoxFuture<'a, T> = Pin<Box<dyn Future<Output = T> + 'a>>;

/// Logs in and turns the stored credential into a bearer token. An API key given by
/// `--api-key` or `<PREFIX>_API_KEY` skips it; `auth login --api-key` stores one without it.
pub trait Auth: Sync {
    /// Flags added to `auth login`, read back from `args` in [`Auth::login`].
    fn login_args(&self) -> Vec<Arg> {
        Vec::new()
    }

    /// `auth login`: the credential to store in `ctx.profile()`.
    fn login<'a>(
        &'a self,
        ctx: &'a mut Ctx,
        args: &'a ArgMatches,
    ) -> BoxFuture<'a, Result<Credential, CliError>>;

    /// The token of each command (`ctx.token().await?`). Changes to `credential`, such as a
    /// refresh, are saved to the profile.
    fn token<'a>(
        &'a self,
        ctx: &'a mut Ctx,
        credential: &'a mut Credential,
    ) -> BoxFuture<'a, Result<String, CliError>>;

    /// `auth logout`, before the credential is removed, e.g. to revoke it. Errors are warnings.
    fn logout<'a>(
        &'a self,
        _ctx: &'a mut Ctx,
        _credential: &'a Credential,
    ) -> BoxFuture<'a, Result<(), CliError>> {
        Box::pin(async { Ok(()) })
    }

    /// The `auth` column of `auth profiles`, and `--debug`.
    fn status(&self, credential: &Credential) -> String {
        credential.describe(config::now())
    }
}

/// An API key, prompted for without echo on a terminal, else read from stdin. Its token is
/// the key, or a stored access token.
#[derive(Clone, Copy, Debug, Default)]
pub struct ApiKey;

impl Auth for ApiKey {
    fn login<'a>(
        &'a self,
        ctx: &'a mut Ctx,
        _args: &'a ArgMatches,
    ) -> BoxFuture<'a, Result<Credential, CliError>> {
        Box::pin(async move {
            let key = if ctx.stdin_tty() {
                let profile = ctx.profile();
                rpassword::prompt_password(format!("API key for profile `{profile}`: "))?
            } else {
                let mut line = String::new();
                io::BufReader::new(ctx.stdin()).read_line(&mut line)?;
                line
            };
            let key = key.trim();
            if key.is_empty() {
                return Err(CliError::usage("login: the API key is empty"));
            }
            Ok(Credential::api_key(key))
        })
    }

    fn token<'a>(
        &'a self,
        ctx: &'a mut Ctx,
        credential: &'a mut Credential,
    ) -> BoxFuture<'a, Result<String, CliError>> {
        let token = credential
            .api_key
            .clone()
            .or_else(|| credential.access_token.clone())
            .ok_or_else(|| ctx.login_required());
        Box::pin(async move { token })
    }
}

/// One way to log in, chosen by `auth login --<flag>`.
#[derive(Clone, Copy)]
pub struct Method {
    pub flag: &'static str,
    pub help: &'static str,
    pub auth: &'static dyn Auth,
}

impl Method {
    pub const fn new(flag: &'static str, help: &'static str, auth: &'static dyn Auth) -> Self {
        Self { flag, help, auth }
    }
}

/// `default` unless a method's flag is given, e.g. an API key by default, `--web` for a
/// browser login. The credential records its method, which then refreshes it.
#[derive(Clone, Copy)]
pub struct Methods {
    pub default: &'static dyn Auth,
    pub methods: &'static [Method],
}

impl Methods {
    fn of(&self, credential: &Credential) -> &'static dyn Auth {
        let method = credential.method.as_deref();
        self.methods
            .iter()
            .find(|m| Some(m.flag) == method)
            .map_or(self.default, |m| m.auth)
    }
}

impl Auth for Methods {
    fn login_args(&self) -> Vec<Arg> {
        let flags: Vec<&str> = self.methods.iter().map(|m| m.flag).collect();
        let mut args: Vec<Arg> = self
            .methods
            .iter()
            .map(|m| {
                let others = flags.iter().filter(|flag| **flag != m.flag);
                Arg::new(m.flag)
                    .long(m.flag)
                    .help(m.help)
                    .action(ArgAction::SetTrue)
                    .conflicts_with_all(others)
            })
            .collect();
        let inner = std::iter::once(self.default).chain(self.methods.iter().map(|m| m.auth));
        for arg in inner.flat_map(|auth| auth.login_args()) {
            if !args.iter().any(|a| a.get_id() == arg.get_id()) {
                args.push(arg);
            }
        }
        args
    }

    fn login<'a>(
        &'a self,
        ctx: &'a mut Ctx,
        args: &'a ArgMatches,
    ) -> BoxFuture<'a, Result<Credential, CliError>> {
        Box::pin(async move {
            let chosen = self.methods.iter().find(|m| args.get_flag(m.flag));
            let Some(method) = chosen else {
                return self.default.login(ctx, args).await;
            };
            let mut credential = method.auth.login(ctx, args).await?;
            credential.method = Some(method.flag.to_owned());
            Ok(credential)
        })
    }

    fn token<'a>(
        &'a self,
        ctx: &'a mut Ctx,
        credential: &'a mut Credential,
    ) -> BoxFuture<'a, Result<String, CliError>> {
        self.of(credential).token(ctx, credential)
    }

    fn logout<'a>(
        &'a self,
        ctx: &'a mut Ctx,
        credential: &'a Credential,
    ) -> BoxFuture<'a, Result<(), CliError>> {
        self.of(credential).logout(ctx, credential)
    }

    fn status(&self, credential: &Credential) -> String {
        let status = self.of(credential).status(credential);
        match &credential.method {
            Some(method) => format!("{status} (--{method})"),
            None => status,
        }
    }
}

/// Opens `url` with `$BROWSER` or the platform's opener when stderr is a terminal and
/// `BROWSER` is not `none`. Returns whether it tried; callers print the URL either way.
pub fn open_browser(ctx: &Ctx, url: &str) -> bool {
    if !ctx.stderr_tty() {
        return false;
    }
    let mut command = match ctx.env("BROWSER") {
        Some("none" | "false" | "0") => return false,
        Some(browser) => Process::new(browser),
        None if cfg!(target_os = "macos") => Process::new("open"),
        None if cfg!(windows) => {
            let mut command = Process::new("rundll32");
            command.arg("url.dll,FileProtocolHandler");
            command
        }
        None => Process::new("xdg-open"),
    };
    command
        .arg(url)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .is_ok()
}

pub(super) async fn login(ctx: &mut Ctx, args: &ArgMatches) -> Result<(), CliError> {
    let path = ctx.config_path()?.to_owned();
    let auth = ctx.app.auth;
    let from_stdin = args.get_flag("api-key-stdin");
    let key = match (ctx.globals.api_key.clone(), from_stdin) {
        (Some(_), true) => {
            return Err(CliError::usage(
                "login: --api-key and --api-key-stdin both give the key: pick one",
            ))
        }
        (Some(key), false) => Some(key),
        (None, true) => {
            let mut line = String::new();
            io::BufReader::new(ctx.stdin()).read_line(&mut line)?;
            Some(line)
        }
        (None, false) => None,
    };
    let mut credential = match key {
        Some(key) if key.trim().is_empty() => {
            return Err(CliError::usage("login: the API key is empty"))
        }
        Some(key) => Credential::api_key(key.trim()),
        None => auth.login(ctx, args).await?,
    };
    let status = auth.status(&credential);
    let profile = ctx.profile().to_owned();
    let app = ctx.app.name;
    let no_keyring = args.try_get_one::<bool>("no-keyring").ok().flatten() == Some(&true)
        || ctx
            .env(&format!("{}_NO_KEYRING", ctx.app.env_prefix))
            .is_some_and(|value| !matches!(value, "0" | "false"));
    let mut sealed = false;
    if keyring::ENABLED && !no_keyring {
        match keyring::store(app, &profile, &mut credential) {
            Ok(()) => sealed = true,
            Err(error) => writeln!(
                ctx.stderr(),
                "warning: the OS keyring is unavailable ({error}): the secrets go to the config file"
            )?,
        }
    }
    let _lock = ConfigFile::lock(&path)?;
    let mut file = ConfigFile::load(&path)?;
    let before = file.profiles.get(&profile).map(|p| &p.credential);
    if !sealed && before.is_some_and(keyring::sealed) {
        if let Err(error) = keyring::delete(app, &profile) {
            writeln!(
                ctx.stderr(),
                "warning: cannot clear the OS keyring: {error}"
            )?;
        }
    }
    file.login(&profile, credential, ctx.globals.base_url.clone());
    file.save(&path)?;
    let secrets = if sealed {
        ", its secrets in the OS keyring"
    } else {
        ""
    };
    writeln!(
        ctx.stderr(),
        "Logged in to profile `{profile}` ({status}), saved to {}{secrets}",
        path.display()
    )?;
    Ok(())
}

/// Removes the credential, then lets the hook revoke it, outside the config file's lock.
pub(super) async fn logout(ctx: &mut Ctx) -> Result<(), CliError> {
    let path = ctx.config_path()?.to_owned();
    let profile = ctx.profile().to_owned();
    let lock = ConfigFile::lock(&path)?;
    let mut file = ConfigFile::load(&path)?;
    let Some(mut credential) = file.logout(&profile) else {
        writeln!(ctx.stderr(), "Profile `{profile}` has no credential")?;
        return Ok(());
    };
    if keyring::sealed(&credential) {
        if let Err(error) = ctx.unseal(&mut credential) {
            ctx.debug(format_args!("not revoked: {error}"));
        }
        if let Err(error) = keyring::delete(ctx.app.name, &profile) {
            writeln!(
                ctx.stderr(),
                "warning: cannot clear the OS keyring: {error}"
            )?;
        }
    }
    file.save(&path)?;
    drop(lock);
    let auth = ctx.app.auth;
    if let Err(error) = auth.logout(ctx, &credential).await {
        writeln!(ctx.stderr(), "warning: {error}")?;
    }
    writeln!(
        ctx.stderr(),
        "Removed the credential of profile `{profile}`"
    )?;
    Ok(())
}

/// `auth status`: the credential commands use, never its secret. Exits 6 without one.
pub(super) fn status(ctx: &mut Ctx) -> Result<(), CliError> {
    let credentials = ctx.credentials.clone();
    let base_url = ctx.api_base_url().map(super::app::redact_userinfo);
    let mut credential = credentials.credential.clone();
    let explicit = credentials.api_key.is_some();
    let unsealed = match explicit {
        true => Ok(()),
        false => ctx.unseal(&mut credential),
    };
    let now = config::now();
    let (method, source, expires_at, refreshable, auth) = match &credentials.api_key {
        Some(key) => (
            Some("api_key".to_owned()),
            credentials.api_key_source.to_string(),
            None,
            false,
            Some(format!("api key {}", config::mask(key))),
        ),
        None if credential.is_empty() => (None, String::new(), None, false, None),
        None => {
            let method = credential.method.clone().or_else(|| {
                let kind = match (&credential.api_key, &credential.access_token) {
                    (Some(_), _) => "api_key",
                    (None, Some(_)) => "oauth",
                    (None, None) => "custom",
                };
                Some(kind.to_owned())
            });
            let auth = match &unsealed {
                Ok(()) => ctx.app.auth.status(&credential),
                Err(error) => error.to_string(),
            };
            (
                method,
                Source::Profile(credentials.profile.clone()).to_string(),
                credential.expires_at,
                credential.refresh_token.is_some(),
                Some(auth),
            )
        }
    };
    let logged_in = auth.is_some() && unsealed.is_ok();
    let storage = match (explicit, credential.is_empty()) {
        (true, _) | (_, true) => None,
        (false, false) if keyring::sealed(&credential) => Some("keyring"),
        (false, false) => Some("file"),
    };
    ctx.print(&json!({
        "profile": credentials.profile,
        "logged_in": logged_in,
        "method": method,
        "source": (!source.is_empty()).then_some(source),
        "auth": auth,
        "expires_at": expires_at,
        "expires_in": expires_at.map(|at| at - now),
        "refreshable": refreshable,
        "base_url": base_url,
        "storage": storage,
    }))?;
    match (logged_in, unsealed) {
        (_, Err(error)) => Err(error),
        (false, _) => Err(ctx.login_required()),
        (true, _) => Ok(()),
    }
}

/// `auth token`: the bearer token, for `curl -H "Authorization: Bearer $(acme auth token)"`.
pub(super) async fn token(ctx: &mut Ctx) -> Result<(), CliError> {
    let token = ctx.token().await?;
    let out = ctx.out.writer();
    writeln!(out, "{token}")?;
    Ok(out.flush()?)
}

pub(super) fn profiles(ctx: &mut Ctx, file: &ConfigFile) -> Result<(), CliError> {
    let auth = ctx.app.auth;
    let rows: Vec<Value> = file
        .profiles
        .iter()
        .map(|(name, profile)| {
            let mut credential = profile.credential.clone();
            let status = match keyring::load(ctx.app.name, name, &mut credential) {
                Ok(()) => auth.status(&credential),
                Err(error) => error.to_string(),
            };
            json!({
                "name": name,
                "default": name == file.default_profile(),
                "base_url": profile.base_url,
                "auth": (!credential.is_empty()).then_some(status),
            })
        })
        .collect();
    ctx.print(&rows)
}
